ALTER TABLE app.tema ADD COLUMN IF NOT EXISTS modulo TEXT;
ALTER TABLE app.tema ADD COLUMN IF NOT EXISTS ordem_principal SMALLINT;
CREATE UNIQUE INDEX IF NOT EXISTS uq_tema_ordem_principal ON app.tema (ciclo_id, ordem_principal) WHERE ordem_principal IS NOT NULL;
UPDATE app.tema SET ordem_principal = NULL;

